"use strict";(globalThis.webpackChunkmy_website||=[]).push([[88322],{35869(e){e.exports=JSON.parse('{"slug":"hard-fork","title":"Hard Fork","short":"A network upgrade that changes the blockchain\'s rules in a way older software versions no longer understand; every node has to update before the change takes effect.","category":"network","aliases":["Upgrade","Protocol Upgrade"],"mentalModel":"Like upgrading an operating system: after the upgrade, only nodes running the new version can keep talking to the network.","related":["soft-fork","hard-fork-combinator","allegra","alonzo","mary","vasil","chang","plomin","van-rossem","dijkstra"],"sources":[],"link":"/hardforks","level":"beginner","body":"Cardano uses a [hard fork combinator](/glossary/hard-fork-combinator) to keep the chain alive through these transitions instead of splitting it. See [hard forks](/hardforks/) for the full upgrade history."}')}}]);